// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import * as random from '@stdlib/types/random';

/**
* Interface defining `factory` options.
*/
interface Options {
	/**
	* Pseudorandom number generator seed.
	*/
	seed?: random.PRNGSeedPCG32;

	/**
	* Pseudorandom number generator state.
	*/
	state?: random.PRNGStatePCG32;

	/**
	* Specifies whether to copy a provided pseudorandom number generator state.
	*/
	copy?: boolean;
}

/**
* Interface for PRNG properties and methods.
*/
interface PRNG {
	/**
	* Generator name.
	*/
	readonly NAME: string;

	/**
	* Minimum possible value.
	*/
	readonly MIN: number;

	/**
	* Maximum possible value.
	*/
	readonly MAX: number;

	/**
	* PRNG seed.
	*/
	readonly seed: random.PRNGSeedPCG32;

	/**
	* PRNG seed length.
	*/
	readonly seedLength: number;

	/**
	* PRNG state.
	*/
	state: random.PRNGStatePCG32;

	/**
	* PRNG state length.
	*/
	readonly stateLength: number;

	/**
	* PRNG state size (in bytes).
	*/
	readonly byteLength: number;

	/**
	* Serializes the pseudorandom number generator as a JSON object.
	*
	* @returns JSON representation
	*/
	toJSON(): string;
}

/**
* Interface for generating pseudorandom integers on the interval `[0, 4294967295]`.
*/
interface NullaryFunction extends PRNG {
	/**
	* Returns a pseudorandom integer on the interval `[0, 4294967295]`.
	*
	* @returns pseudorandom number
	*/
	(): number;
}

/**
* Interface for generating pseudorandom integers on the interval `[0, 4294967295]`.
*/
interface Random extends PRNG {
	/**
	* Returns a pseudorandom integer on the interval `[0, 4294967295]`.
	*
	* ## Notes
	*
	* -   This pseudorandom number generator (PRNG) is a permuted congruential pseudorandom number generator (PCG) based on O’Neill.
	* -   The generator has a period of `2^64`.
	* -   An LCG is fast and uses little memory. On the other hand, because the generator is a simple LCG, the generator has recognized shortcomings. By today's PRNG standards, the generator's period is relatively short. More importantly, the "randomness quality" of the generator's output is lacking. These defects make the generator unsuitable, for example, in Monte Carlo simulations and in cryptographic applications.
	*
	* @returns pseudorandom number
	*
	* @example
	* var v = pcg32();
	* // returns <number>
	*/
	(): number;

	/**
	* Returns a pseudorandom number on the interval `[0,1)`.
	*
	* @returns pseudorandom number
	*
	* @example
	* var r = pcg32.normalized();
	* // returns <number>
	*/
	normalized(): number;

	/**
	* Returns a permuted congruential pseudorandom number generator (PCG).
	*
	* @param options - function options
	* @param options.seed - pseudorandom number generator seed
	* @param options.state - pseudorandom number generator state
	* @param options.copy - boolean indicating whether to copy a provided pseudorandom number generator state (default: true)
	* @throws must provide valid options
	* @returns pseudorandom number generator
	*
	* @example
	* var rand = pcg32.factory();
	* var v = rand();
	* // returns <number>
	*
	* @example
	* var rand = pcg32.factory({
	*     'seed': 12345
	* });
	* var v = rand();
	* // returns <number>
	*/
	factory( options?: Options ): NullaryFunction;
}

/**
* Returns a pseudorandom integer on the interval `[0, 4294967295]`.
*
* ## Notes
*
* -   This pseudorandom number generator (PRNG) is a permuted congruential pseudorandom number generator (PCG) based on O’Neill.
* -   The generator has a period of `2^64`.
* -   An LCG is fast and uses little memory. On the other hand, because the generator is a simple LCG, the generator has recognized shortcomings. By today's PRNG standards, the generator's period is relatively short. More importantly, the "randomness quality" of the generator's output is lacking. These defects make the generator unsuitable, for example, in Monte Carlo simulations and in cryptographic applications.
*
* @returns pseudorandom number
*
* @example
* var v = pcg32();
* // returns <number>
*
* @example
* var v = pcg32.normalized();
* // returns <number>
*
* @example
* var rand = pcg32.factory({
*     'seed': 12345
* });
* var v = rand();
* // returns <number>
*/
declare var pcg32: Random;


// EXPORTS //

export = pcg32;
